package com.print.kiosk.service.impl;
import com.print.kiosk.entity.PrintRequestFile;import com.print.kiosk.repository.PrintRequestFileRepository;import com.print.kiosk.service.interfaces.FileCleanupService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class FileCleanupServiceImpl implements FileCleanupService{private static final ZoneId DHAKA=ZoneId.of("Asia/Dhaka");private final PrintRequestFileRepository files;public FileCleanupServiceImpl(PrintRequestFileRepository f){files=f;}@Transactional public int deleteEligibleFileContent(){LocalDateTime now=LocalDateTime.now(DHAKA);List<PrintRequestFile> due=files.findTop100ByDeletionEligibleAtLessThanEqualAndBinaryDeletedAtIsNullAndFileDataIsNotNullOrderByDeletionEligibleAtAsc(now);for(PrintRequestFile f:due){f.setFileData(null);f.setBinaryDeletedAt(now);}files.saveAll(due);return due.size();}}